1	package cli
2	
3	import (
4		"database/sql"
5		"fmt"
6		"os"
7		"path/filepath"
8		"sort"
9		"strconv"
10		"strings"
11		"time"
12	)
13	
14	// history_fts.go builds a derived FTS5 BM25 index over the history records and
15	// ranks the history arm of the unified search/query verbs with it. It is a rebuildable artifact, a
16	// sibling of history/index.json (the truth): deleting the .sqlite file forces a
17	// clean rebuild on the next query, and any open/build/query failure falls back
18	// to the substring scorer, so the index is an optimization, never load-bearing.
19	//
20	// BM25 replaces the hand-rolled coverage gate (historyRequiredQueryMatches),
21	// whose flat term-counting could not tell a high-value term ("embedding") from a
22	// filler one ("one"/"state"): every relaxation of the gate that admitted a real
23	// single-strong-term paraphrase also admitted two-weak-term noise. BM25's IDF
24	// down-weights common terms by corpus frequency, so an OR of the query terms
25	// surfaces the doc that is strongly about the rare term while honest empties
26	// (no term present at all) still return nothing.
27	
28	const (
29		historyFTSFileName = "index-fts.sqlite"
30		historyFTSSchema   = "1"
31	)
32	
33	// historyFTSRelevanceCutoff keeps only matches scoring at least this fraction of
34	// the query's top match. BM25 score magnitude is not comparable across queries,
35	// but within one query it is: an OR query matches every record sharing any term,
36	// so a strong query grows a long tail of records that matched only one common or
37	// stemmed term (e.g. "updates" hitting "Update File") far below the best hit.
38	// Cutting relative to the top — not an absolute floor — trims that tail without a
39	// corpus-specific constant. Tunable once a history eval lands.
40	const historyFTSRelevanceCutoff = 0.30
41	
42	func historyFTSDBPath(brainDir string) string {
43		return filepath.Join(brainDir, historyDirName, historyFTSFileName)
44	}
45	
46	// historyFTSContent is the searchable text for a record. It indexes two forms so
47	// both spaced and camelCase queries hit the same identifier: the camel-split,
48	// lowercased normalization (so "attribution base" matches "AttributionBaseCommit")
49	// and the raw lowercase (so the single token "attributionbasecommit" matches too)
50	// — the same dual normalized/raw strategy the substring matcher already uses.
51	func historyFTSContent(r historyRecord) string {
52		raw := r.Summary + " " + strings.Join(r.Terms, " ") + " " + r.Path
53		return normalizeHistorySearchText(raw) + " " + strings.ToLower(raw)
54	}
55	
56	// historyFTSMatchExpr turns a query into a safe FTS5 OR expression over its
57	// stopword-filtered terms and identifiers. Each term is wrapped as an FTS5 string
58	// literal (double-quoted, embedded quotes doubled) so query operators and
59	// punctuation can never reach the FTS parser. Empty when the query reduces to no
60	// usable term, which the caller treats as "fall back to the substring scorer".
61	func historyFTSMatchExpr(query string) string {
62		parts := make([]string, 0, 8)
63		for _, t := range historyQueryAllTerms(query) {
64			t = strings.ToLower(strings.TrimSpace(t))
65			if t == "" {
66				continue
67			}
68			parts = append(parts, `"`+strings.ReplaceAll(t, `"`, `""`)+`"`)
69		}
70		if len(parts) == 0 {
71			return ""
72		}
73		return strings.Join(parts, " OR ")
74	}
75	
76	func historyFTSFingerprint(index historyIndex) string {
77		return index.GeneratedAt.UTC().Format(time.RFC3339Nano) + ":" + strconv.Itoa(len(index.Records))
78	}
79	
80	// openHistoryFTS opens (and rebuilds if stale) the derived BM25 index. The index
81	// is keyed by a fingerprint of the history index it was built from, so a refresh
82	// that regenerates history/index.json triggers a clean rebuild here.
83	func openHistoryFTS(brainDir string, index historyIndex) (*sql.DB, error) {
84		path := historyFTSDBPath(brainDir)
85		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
86			return nil, err
87		}
88		db, err := sql.Open(sqliteDriverName, path)
89		if err != nil {
90			return nil, err
91		}
92		// Pin a single connection so connection-scoped PRAGMAs (busy_timeout) below
93		// apply to every query/build, not just whichever pooled connection ran them.
94		db.SetMaxOpenConns(1)
95		for _, pragma := range []string{"PRAGMA busy_timeout=5000;", "PRAGMA journal_mode=WAL;"} {
96			if _, err := db.Exec(pragma); err != nil {
97				db.Close()
98				return nil, err
99			}
100		}
101		if historyFTSFresh(db, index) {
102			return db, nil
103		}
104		if err := buildHistoryFTS(db, index); err != nil {
105			db.Close()
106			return nil, err
107		}
108		return db, nil
109	}
110	
111	// historyFTSFresh reports whether the existing index matches the current history
112	// index. Any error (missing tables, unreadable meta) is treated as stale so the
113	// caller rebuilds rather than failing.
114	func historyFTSFresh(db *sql.DB, index historyIndex) bool {
115		rows, err := db.Query(`SELECT key, value FROM history_fts_meta`)
116		if err != nil {
117			return false
118		}
119		defer rows.Close()
120		got := map[string]string{}
121		for rows.Next() {
122			var k, v string
123			if err := rows.Scan(&k, &v); err != nil {
124				return false
125			}
126			got[k] = v
127		}
128		if rows.Err() != nil {
129			return false // a driver error mid-iteration must read as stale, not fresh
130		}
131		return got["schema"] == historyFTSSchema && got["fingerprint"] == historyFTSFingerprint(index)
132	}
133	
134	func buildHistoryFTS(db *sql.DB, index historyIndex) error {
135		tx, err := db.Begin()
136		if err != nil {
137			return err
138		}
139		defer tx.Rollback()
140		for _, stmt := range []string{
141			`DROP TABLE IF EXISTS history_fts`,
142			`DROP TABLE IF EXISTS history_fts_meta`,
143			`CREATE TABLE history_fts_meta(key TEXT PRIMARY KEY, value TEXT)`,
