29	func newRetrieveCommand(opts Options, use string, mode retrievalMode, short string) *cobra.Command {
30		var jsonOut bool
31		var limit int
32		var branch string
33		cmd := &cobra.Command{
34			Use:   use + " <query>",
35			Short: short,
36			Args:  cobra.ExactArgs(1),
37			RunE: func(cmd *cobra.Command, args []string) error {
38				return runRetrieve(cmd.Context(), cmd, opts, args[0], mode, limit, branch, jsonOut)
39			},
40		}
41		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit machine-readable JSON")
42		cmd.Flags().IntVar(&limit, "limit", 10, "Maximum results")
43		cmd.Flags().StringVar(&branch, "branch", "", "Branch for facts (default: current)")
44		return cmd
45	}
