47	func runRetrieve(ctx context.Context, cmd *cobra.Command, opts Options, query string, mode retrievalMode, limit int, branch string, jsonOut bool) error {
48		// Reject --limit <= 0 rather than silently defaulting, so a typo like
49		// `--limit 0` is an explicit error (matching the rest of the CLI surface). The
50		// MCP path passes a validated positive limit, so it's unaffected.
51		if limit <= 0 {
52			return fmt.Errorf("--limit must be greater than 0")
53		}
54		_, brainDir, resolvedBranch, err := resolveFactsTarget(ctx, opts, agentSurfaceTarget(opts, nil), branch)
55		if err != nil {
56			return err
57		}
58		results, err := retrieveUnified(brainDir, resolvedBranch, query, limit, mode)
59		if err != nil {
60			return err
61		}
62		if jsonOut {
63			return writeJSON(cmd, map[string]any{"query": query, "branch": resolvedBranch, "results": results})
64		}
65		if len(results) == 0 {
66			fmt.Fprintf(cmd.OutOrStdout(), "no results for %q\n", query)
67			return nil
68		}
69		for _, r := range results {
70			ex := truncateString(strings.Join(strings.Fields(r.Text), " "), 200)
71			loc := r.Path
72			if r.Line > 0 {
73				loc = fmt.Sprintf("%s:%d", r.Path, r.Line)
74			}
75			fmt.Fprintf(cmd.OutOrStdout(), "[%s] %s  %s\n    %s\n", r.Source, r.ID, loc, ex)
76		}
77		return nil
78	}
