112	func runGet(ctx context.Context, cmd *cobra.Command, opts Options, ids []string, branch string, jsonOut bool) error {
113		_, brainDir, resolvedBranch, err := resolveFactsTarget(ctx, opts, agentSurfaceTarget(opts, nil), branch)
114		if err != nil {
115			return err
116		}
117		found, missing, err := getUnifiedBatch(brainDir, resolvedBranch, ids)
118		if err != nil {
119			return err
120		}
121		// Normalize empty collections to [] so --json emits arrays, not null, matching
122		// the repo's JSON contract (see TestInspectCodeEmptyResultsEmitArrayNotNull).
