26		progress    *refreshProgress
27		label       string
28		lastPrinted string
29		lastStatus  string
30		lastPrintAt time.Time
31		done        chan struct{}
32		stopped     chan struct{}
33	}
34	
35	func newRefreshProgress(out io.Writer) *refreshProgress {
36		return newProgress(out, "refresh")
37	}
