39	// newProgress builds a progress reporter whose non-TTY lines are prefixed with
40	// the given command name (for example "refresh" or "distill"). On a TTY it
41	// renders a single in-place spinner line instead.
42	func newProgress(out io.Writer, prefix string) *refreshProgress {
43		spinner := false
44		if file, ok := out.(*os.File); ok {
45			spinner = isatty.IsTerminal(file.Fd())
46		}
47		return &refreshProgress{
48			out:     out,
49			prefix:  prefix,
50			spinner: spinner,
51		}
52	}
53	
54	func (p *refreshProgress) Step(label string) func(error) {
55		task := p.Begin(label)
56		return task.Finish
57	}
58	
59	func (p *refreshProgress) Begin(label string) *refreshProgressTask {
60		if p == nil || p.out == nil {
61			return &refreshProgressTask{}
62		}
63		task := &refreshProgressTask{
64			progress:    p,
65			label:       label,
66			lastPrinted: label,
67			lastStatus:  progressStatusKey(label),
68			lastPrintAt: time.Now(),
69		}
70		if p.spinner {
71			task.done = make(chan struct{})
72			task.stopped = make(chan struct{})
73			task.startSpinner()
74			return task
75		}
76		fmt.Fprintf(p.out, "%s: %s\n", p.prefix, label)
77		return task
78	}
79	
80	func (p *refreshProgress) Skip(label string) {
81		if p == nil || p.out == nil {
82			return
83		}
84		fmt.Fprintf(p.out, "%s: %s skipped\n", p.prefix, label)
85	}
86	
87	func (t *refreshProgressTask) Update(label string) {
88		if t == nil || t.progress == nil || t.progress.out == nil {
89			return
90		}
91		t.progress.mu.Lock()
92		t.label = label
93		if t.progress.spinner {
94			fmt.Fprintf(t.progress.out, "%s%s", clearTerminalLine, spinnerLine('|', label))
95		} else if t.shouldPrintUpdate(label) {
96			fmt.Fprintf(t.progress.out, "%s: %s\n", t.progress.prefix, label)
97			t.lastPrinted = label
98			t.lastStatus = progressStatusKey(label)
99			t.lastPrintAt = time.Now()
100		}
101		t.progress.mu.Unlock()
102	}
103	
104	func (t *refreshProgressTask) shouldPrintUpdate(label string) bool {
105		if label == t.lastPrinted {
106			return false
107		}
108		status := progressStatusKey(label)
109		if status != t.lastStatus {
110			return true
111		}
112		return time.Since(t.lastPrintAt) >= time.Second
113	}
114	
115	func (t *refreshProgressTask) Finish(err error) {
116		if t == nil || t.progress == nil || t.progress.out == nil {
117			return
118		}
119		if t.done != nil {
120			close(t.done)
121			<-t.stopped
122		}
123		t.progress.mu.Lock()
124		defer t.progress.mu.Unlock()
125		if err != nil {
126			if t.progress.spinner {
127				fmt.Fprintf(t.progress.out, "%s! %s failed\n", clearTerminalLine, t.label)
128				return
129			}
130			fmt.Fprintf(t.progress.out, "%s: %s failed\n", t.progress.prefix, t.label)
131			return
132		}
133		if t.progress.spinner {
134			fmt.Fprintf(t.progress.out, "%s+ %s done\n", clearTerminalLine, t.label)
135			return
136		}
137		fmt.Fprintf(t.progress.out, "%s: %s done\n", t.progress.prefix, t.label)
138	}
139	
140	func (t *refreshProgressTask) startSpinner() {
141		frames := []rune{'|', '/', '-', '\\'}
142		go func() {
143			defer close(t.stopped)
144			ticker := time.NewTicker(120 * time.Millisecond)
145			defer ticker.Stop()
146			i := 0
147			for {
148				select {
149				case <-t.done:
150					return
151				case <-ticker.C:
152					t.progress.mu.Lock()
153					fmt.Fprintf(t.progress.out, "%s%s", clearTerminalLine, spinnerLine(frames[i%len(frames)], t.label))
154					t.progress.mu.Unlock()
155					i++
156				}
157			}
158		}()
159		t.progress.mu.Lock()
160		fmt.Fprintf(t.progress.out, "%s%s", clearTerminalLine, spinnerLine(frames[0], t.label))
161		t.progress.mu.Unlock()
162	}
163	
164	func spinnerLine(frame rune, label string) string {
165		return fmt.Sprintf("%c %s", frame, label)
166	}
167	
168	func progressStatusKey(label string) string {
169		return progressCountPattern.ReplaceAllString(label, "")
170	}
