		return
	}
	fmt.Fprintf(t.progress.out, "%s: %s done\n", t.progress.prefix, t.label)
}

func (t *refreshProgressTask) startSpinner() {
	frames := []rune{'|', '/', '-', '\\'}
	go func() {
		defer close(t.stopped)
		ticker := time.NewTicker(120 * time.Millisecond)
		defer ticker.Stop()
