// evalRelevanceSourcesComparable reports whether two results share the SAME
// ground truth — same labeled-ness, same relevance source, and (for explicit
// labels) the same label source. Same-truth comparisons are statistically
// meaningful regardless of evidence grade: two provenance_silver runs over one
// task set compare apples to apples. Whether the comparison is CLAIMABLE as
// release proof is a separate, stricter question (evalRelevanceSourceIsProofLabel
// → EvidenceBasis); conflating the two made `eval-compare` hard-error on its
// own default eval-gen output and on every history-eval summary.
func evalRelevanceSourcesComparable(a, b evalTaskResult) bool {
	if a.RelevanceSource == "" || b.RelevanceSource == "" {
		return false
	}
	if a.Labeled != b.Labeled || a.RelevanceSource != b.RelevanceSource {
		return false
	}
	if a.RelevanceSource == evalRelevanceExplicitLabel {
		return strings.TrimSpace(a.LabelSource) == strings.TrimSpace(b.LabelSource)
	}
	return true
}

