	if _, err := runDistillForBrain(context.Background(), t.TempDir(), brainDir, opts, now); err != nil {
		t.Fatalf("second run: %v", err)
	}
	if calls == 0 {
		t.Fatal("changed session must re-distill, not be grandfathered")
