class BrainQueryAnswerLeakAuditTest(unittest.TestCase):
    """Release blocker B1: brain_queries reach brain-arm prompts only, so a
    query term present in hidden task material but absent from the prompt is
    an answer-bearing hint the no-brain arm cannot see."""

    def test_identifier_in_hidden_validation_is_flagged(self) -> None:
        task = {
            "prompt": "The checks summary line regressed.",
            "brain_queries": ["PrCheckStatusSummaryWithColor"],
            "validation": ["go test ./pkg -run '^TestPrCheckStatusSummaryWithColor$'"],
        }
        leaks = run.audit_brain_query_answer_leaks(task)
        self.assertEqual(len(leaks), 1)
        self.assertIn("PrCheckStatusSummaryWithColor", leaks[0])

    def test_prompt_shared_symptom_vocabulary_is_not_flagged(self) -> None:
        task = {
            "prompt": "Names with a trailing .git suffix are no longer normalized.",
            "brain_queries": ["trailing .git suffix normalization"],
            "validation": ["go test ./internal/repo -run '^TestNormalizeTrailingSuffix$'"],
        }
        # "suffix" and "normalization"-adjacent terms appear in the prompt:
        # both arms see them, so there is no asymmetry to flag.
        self.assertEqual(run.audit_brain_query_answer_leaks(task), [])

    def test_injected_string_terms_are_flagged(self) -> None:
        task = {
            "prompt": "The tenant identity has a stray dot.",
            "brain_queries": ["tenancyHost detection"],
            "setup_replacements": [{"path": "x.go", "old": "tenancyHost(h)", "new": "h"}],
        }
        leaks = run.audit_brain_query_answer_leaks(task)
        self.assertEqual(len(leaks), 1)
        self.assertIn("tenancyHost", leaks[0])

    def test_no_queries_is_clean(self) -> None:
        self.assertEqual(run.audit_brain_query_answer_leaks({"prompt": "x", "validation": ["y"]}), [])
