func runWorkspaceList(cmd *cobra.Command, opts Options, asJSON bool) error {
	dirs, err := resolvePluginDirs(opts.Env)
	if err != nil {
		return err
	}
	root := filepath.Join(dirs.Data, repoStoreDirName, workspaceDirName)
