1	//go:build brain_cgo
2	
3	package cli
4	
5	import (
6		"database/sql"
7		"encoding/binary"
8		"fmt"
9		"math"
10		"os"
11		"path/filepath"
12		"strconv"
13	
14		sqlitevec "github.com/asg017/sqlite-vec-go-bindings/cgo"
15	)
16	
17	// vecStore is the Stage 1b vector store: fact vectors live in a sqlite-vec
18	// vec0 virtual table (cosine metric) inside facts/<branch>/embeddings/
19	// vectors.sqlite, replacing the vectors.bin flat file + brute-force cosine of
20	// the pure-Go build. The schema is the qmd/Librarian-local shape — vectors in
21	// the same SQLite engine as the FTS index — which is what makes a future
22	// shared local store a read/attach instead of an export.
23	//
24	// Semantics mirror embedStore exactly: the store is a regenerable derived
25	// artifact keyed by embedder model id + dim; load() returns empty on any
26	// mismatch or corruption (a cache miss the caller refills), and save() is a
27	// full atomic rewrite of the touched-and-present vector set, pruning departed
28	// facts. Every method opens the database per call — a CLI invocation does one
29	// load, at most one KNN query, and one save, so holding a handle across the
30	// process buys nothing and leaks on early exits.
31	type vecStore struct {
32		path    string // absolute path to vectors.sqlite
33		modelID string
34		dim     int
35	}
36	
37	const vecStoreFileName = "vectors.sqlite"
38	
39	// newVectorStore on the brain_cgo build returns the vec0-backed store. The
40	// vectors.bin file of the pure-Go build is left untouched: each build
41	// maintains its own derived cache, so switching builds costs one re-embed of
42	// the branch, never corruption.
43	func newVectorStore(brainDir, branch, modelID string, dim int) vectorStore {
44		dir := filepath.Join(brainDir, filepath.FromSlash(factsBranchRelDir(branch)), embedStoreDirName)
45		return &vecStore{path: filepath.Join(dir, vecStoreFileName), modelID: modelID, dim: dim}
46	}
47	
48	func (s *vecStore) open() (*sql.DB, error) {
49		if err := os.MkdirAll(filepath.Dir(s.path), 0o700); err != nil {
50			return nil, err
51		}
52		db, err := sql.Open(sqliteDriverName, s.path)
53		if err != nil {
54			return nil, err
55		}
56		// Pin one connection: the vec0 table and PRAGMAs are connection-scoped
57		// concerns, and the per-call usage pattern never needs concurrency.
58		db.SetMaxOpenConns(1)
59		if _, err := db.Exec("PRAGMA busy_timeout=5000"); err != nil {
60			db.Close()
61			return nil, err
62		}
63		return db, nil
64	}
65	
66	// metaMatches reports whether the store on disk was built for this embedder
67	// model + dim. Any error reads as a mismatch: the store is a cache, so the
68	// degraded path is always "rebuild", never "fail".
69	func (s *vecStore) metaMatches(db *sql.DB) bool {
70		var modelID, dimStr string
71		if err := db.QueryRow(`SELECT value FROM meta WHERE key = 'model_id'`).Scan(&modelID); err != nil {
72			return false
73		}
74		if err := db.QueryRow(`SELECT value FROM meta WHERE key = 'dim'`).Scan(&dimStr); err != nil {
75			return false
76		}
77		dim, err := strconv.Atoi(dimStr)
78		return err == nil && modelID == s.modelID && dim == s.dim && dim > 0
79	}
80	
81	func (s *vecStore) load() map[string][]float32 {
82		out := map[string][]float32{}
83		if _, err := os.Stat(s.path); err != nil {
84			return out
85		}
86		db, err := s.open()
87		if err != nil {
88			return out
89		}
90		defer db.Close()
91		if !s.metaMatches(db) {
92			return out // model/dim mismatch -> full rebuild
93		}
94		rows, err := db.Query(`SELECT f.fact_id, v.embedding FROM vec_facts v JOIN fact_ids f ON f.rowid = v.rowid`)
95		if err != nil {
96			return out
97		}
98		defer rows.Close()
99		for rows.Next() {
100			var id string
101			var blob []byte
102			if err := rows.Scan(&id, &blob); err != nil || len(blob) != 4*s.dim {
103				return map[string][]float32{} // corrupt -> rebuild
104			}
105			vec := make([]float32, s.dim)
106			for d := range vec {
107				vec[d] = math.Float32frombits(binary.LittleEndian.Uint32(blob[4*d:]))
108			}
109			out[id] = vec
110		}
111		if rows.Err() != nil {
112			return map[string][]float32{}
113		}
114		return out
115	}
116	
117	func (s *vecStore) save(vecs map[string][]float32) error {
118		return s.savePresent(vecs, nil)
119	}
120	
121	func (s *vecStore) savePresent(vecs map[string][]float32, present map[string]struct{}) error {
122		if present != nil {
123			merged := s.load()
124			for id := range merged {
125				if _, ok := present[id]; !ok {
126					delete(merged, id)
127				}
128			}
129			for id, vec := range vecs {
130				if _, ok := present[id]; ok {
131					merged[id] = vec
132				}
133			}
134			vecs = merged
135		}
136		db, err := s.open()
137		if err != nil {
138			return err
139		}
140		defer db.Close()
141		// Recreate the schema from scratch on every save: a model or dim change
142		// alters the vec0 column declaration itself, and save() is a full rewrite
143		// anyway, so dropping is both the migration and the prune.
144		ddl := []string{
145			`DROP TABLE IF EXISTS vec_facts`,
146			`DROP TABLE IF EXISTS fact_ids`,
147			`CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY, value TEXT)`,
148			fmt.Sprintf(`CREATE VIRTUAL TABLE vec_facts USING vec0(embedding float[%d] distance_metric=cosine)`, s.dim),
149			`CREATE TABLE fact_ids(rowid INTEGER PRIMARY KEY, fact_id TEXT UNIQUE NOT NULL)`,
150		}
151		for _, stmt := range ddl {
152			if _, err := db.Exec(stmt); err != nil {
153				return err
154			}
155		}
156		tx, err := db.Begin()
157		if err != nil {
158			return err
159		}
160		defer tx.Rollback()
