95	func runRefresh(ctx context.Context, cmd *cobra.Command, opts Options, refreshOpts refreshCommandOptions) error {
96		if refreshOpts.allBranches && !refreshOpts.semantic {
97			return errors.New("--all-branches requires --semantic")
98		}
99		outputExplicit := cmd.Flags().Changed("output")
100		if outputExplicit && strings.TrimSpace(refreshOpts.outputDir) == "" {
101			return errors.New("--output must not be empty")
102		}
103		repoDir, err := exportRepoDir(opts.Env)
104		if err != nil {
105			return err
106		}
107		if refreshOpts.force {
108			refreshOpts.seed.force = true
109		}
110		if outputExplicit {
111			if refreshOpts.force {
112				if err := removeForcedOutputDir(refreshOpts.outputDir, repoDir); err != nil {
113					return err
114				}
115			} else if _, err := validateExportDirAvailable(refreshOpts.outputDir); err != nil {
116				return err
117			}
118		}
119		if refreshOpts.seed.agent == "auto" {
120			refreshOpts.seed.agent = defaultRefreshAgent(ctx, opts.Runner, repoDir)
121		}
122		progress := newRefreshProgress(cmd.ErrOrStderr())
123		exportCmd := &cobra.Command{Use: "export"}
124		exportCmd.SetOut(io.Discard)
125		exportCmd.SetErr(io.Discard)
126		exportOpts := exportCommandOptions{
127			outputDir:       defaultExportDir,
128			outputExplicit:  outputExplicit,
129			checkpointLimit: refreshOpts.checkpointLimit,
130			entireBinary:    refreshOpts.entireBinary,
131			rawTranscript:   refreshOpts.rawTranscript,
132			scope:           refreshOpts.scope,
133		}
134		if outputExplicit {
135			exportOpts.outputDir = refreshOpts.outputDir
136		}
137		exportTask := progress.Begin("export sessions")
138		exportOpts.progress = func(p exportProgress) {
139			exportTask.Update(refreshExportProgressLabel(p))
140		}
141		exportErr := runExport(ctx, exportCmd, opts, exportOpts)
142		exportTaskFinished := false
143		finishExportTask := func(err error) {
144			if exportTaskFinished {
145				return
146			}
147			exportTask.Finish(err)
148			exportTaskFinished = true
149		}
150		if exportErr == nil {
151			finishExportTask(nil)
152		}
153	
154		storageTask := progress.Begin("locate brain")
155		storage, storageErr := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
156		if storageErr != nil {
157			storageTask.Finish(storageErr)
158			return storageErr
159		}
160		storageTask.Update("locate brain: " + storage.Key)
161		storageTask.Finish(nil)
162		brainDir := storage.BrainDir
163		if outputExplicit {
164			finishOutput := progress.Step("resolve output path")
165			brainDir, err = filepath.Abs(refreshOpts.outputDir)
166			if err != nil {
167				finishOutput(err)
168				return fmt.Errorf("resolve output directory: %w", err)
169			}
170			finishOutput(nil)
171		}
172		manifest, _ := loadBrainManifest(brainDir)
173		needSeed := outputExplicit || refreshOpts.seed.force || seedNeededForBrain(manifest)
174		if exportErr != nil && (manifest == nil || manifest.Sources == nil) {
175			needSeed = true
176		}
177		if exportErr != nil && !needSeed {
178			finishExportTask(exportErr)
179			return exportErr
180		}
181		if exportErr != nil {
182			exportTask.Update("export sessions: unavailable, using seed baseline")
183		}
184		finishExportTask(nil)
185		if needSeed {
186			seedTask := progress.Begin("seed baseline")
187			seedCmd := &cobra.Command{Use: "seed"}
188			seedCmd.SetOut(io.Discard)
189			seedCmd.SetErr(io.Discard)
190			seedOpts := refreshOpts.seed
191			seedOpts.update = true
192			seedOpts.outputExplicit = outputExplicit
193			seedOpts.progress = func(phase string) {
194				seedTask.Update("seed baseline: " + phase)
195			}
196			if outputExplicit {
197				seedOpts.outputDir = brainDir
198			}
199			if err := runSeed(ctx, seedCmd, opts, seedOpts, repoDir); err != nil {
200				seedTask.Finish(err)
201				return err
202			}
203			manifest, _ = loadBrainManifest(brainDir)
204			seedTask.Update(refreshSeedLabel(manifest))
205			seedTask.Finish(nil)
206		} else {
207			progress.Skip(refreshSeedLabel(manifest))
208		}
209		if refreshOpts.historyIndex && (refreshOpts.force || !historyIndexCurrent(brainDir, manifest)) {
210			historyTask := progress.Begin("history index")
211			historyProgress := func(done, total int) {
212				if total <= 0 {
213					return
214				}
215				historyTask.Update(fmt.Sprintf("history index: %d/%d %s scanned", done, total, pluralUnit("session", total)))
216			}
217			historySource, err := writeBrainHistoryIndexAndSource(brainDir, opts.Now().UTC(), historyProgress)
218			if err != nil {
219				historyTask.Finish(err)
220				return err
221			}
222			historyTask.Update(refreshHistoryLabel(historySource))
223			historyTask.Finish(nil)
224			manifest, _ = loadBrainManifest(brainDir)
225		} else if refreshOpts.historyIndex {
226			progress.Skip(refreshHistoryLabel(existingHistorySource(manifest)))
227		}
228		// Doc index: retrievable chunks of the brain's own markdown (seed summaries
229		// + copied repo docs). It derives from seed, not history, so gate it on its own
230		// inputs — rebuild when seed ran, when the docs source is missing, on --force,
231		// or alongside a history-index build — never silently skip it just because
232		// --history-index=false.
233		docsMissing := manifest == nil || manifest.Sources == nil || manifest.Sources.Docs == nil
234		if refreshOpts.historyIndex || needSeed || docsMissing || refreshOpts.force {
235			docTask := progress.Begin("doc index")
236			// A doc-index write failure (permissions, disk full, corrupt manifest) is a
237			// real error: fail the refresh like the history index does, so automation
238			// relying on the exit status isn't told success on an incomplete brain.
239			// (A missing seed is not an error — writeDocIndexAndSource writes an empty
240			// index in that case.)
241			docSource, derr := writeDocIndexAndSource(brainDir, opts.Now().UTC())
242			if derr != nil {
243				docTask.Finish(derr)
244				return derr
