		if cands[a].cos != cands[b].cos {
			return cands[a].cos > cands[b].cos
		}
		return cands[a].rec.ID < cands[b].rec.ID
	})
	if len(cands) > limit {
		cands = cands[:limit]
	}
	out := make([]scoredHistoryRecord, len(cands))
