12	// no marker, gated out). Vectors are assigned per text; unknown text embeds
13	// to a fixed default so Dim always matches.
14	type fakeFusionEmbedder struct {
15		vecs   map[string][]float32
16		embeds []string // every Embed call, for call-count assertions
17		fail   func(text string) bool
18	}
