20	func (f *fakeFusionEmbedder) Embed(text string) []float32 {
21		f.embeds = append(f.embeds, text)
22		if f.fail != nil && f.fail(text) {
23			return nil
24		}
25		if v, ok := f.vecs[text]; ok {
26			return v
27		}
28		return []float32{1, 0}
29	}
30	func (f *fakeFusionEmbedder) Dim() int                    { return 2 }
31	func (f *fakeFusionEmbedder) ID() string                  { return "fake-fusion" }
