34	// memHistoryVecStore is an in-memory historyVectorStore so the sync logic is
35	// testable on both builds (the real vec0 store exists only under brain_cgo).
36	type memHistoryVecStore struct {
37		vecs    map[string][]float32
38		upserts int
39	}
40	
41	func newMemHistoryVecStore() *memHistoryVecStore {
42		return &memHistoryVecStore{vecs: map[string][]float32{}}
43	}
44	
45	func (m *memHistoryVecStore) ids() (map[string]struct{}, bool) {
46		out := make(map[string]struct{}, len(m.vecs))
47		for id := range m.vecs {
48			out[id] = struct{}{}
49		}
50		return out, true
51	}
52	
53	func (m *memHistoryVecStore) upsert(add map[string][]float32, drop []string) error {
54		m.upserts++
55		for _, id := range drop {
56			delete(m.vecs, id)
57		}
58		for id, v := range add {
59			m.vecs[id] = v
60		}
61		return nil
62	}
63	
64	func (m *memHistoryVecStore) knnCos(qvec []float32, k int) (map[string]float64, bool) {
65		if len(m.vecs) == 0 || k <= 0 {
66			return nil, false
67		}
68		type sc struct {
69			id  string
70			cos float64
71		}
72		all := make([]sc, 0, len(m.vecs))
73		for id, v := range m.vecs {
74			all = append(all, sc{id, cosineFloat32(qvec, v)})
75		}
76		sort.Slice(all, func(a, b int) bool { return all[a].cos > all[b].cos })
77		if len(all) > k {
78			all = all[:k]
79		}
80		out := make(map[string]float64, len(all))
81		for _, s := range all {
82			out[s.id] = s.cos
83		}
84		return out, true
85	}
